def paired(Ra, Rb):
    """a - b on the same seeds (mean, sd, t, 95% t-CI, counts at +-.20)."""
    d = np.asarray(Ra, float) - np.asarray(Rb, float)
    n = len(d)
    sd = float(d.std(ddof=1)) if n > 1 else float("nan")
    se = sd / math.sqrt(n) if n > 1 else float("nan")
    tq = T975.get(n - 1)
    ci = ([round(float(d.mean() - tq * se), 4), round(float(d.mean() + tq * se), 4)]
          if (tq and n > 1) else None)
    return dict(mean=round(float(d.mean()), 4), sd=round(sd, 4),
                t=(round(float(d.mean() / se), 3) if se and se > 0 else None),
                ci95=ci, n_up=int((d >= .20).sum()), n_dn=int((d <= -.20).sum()), n=n)


